package com.yonlab.vision;
import java.io.*;import java.nio.file.*;import java.security.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.atomic.*;import java.util.function.BooleanSupplier;
public final class OneImageHandoffCopyHost {
 private static int checks;private static Method copier,mime,extension;
 private static void check(boolean v,String why){checks++;if(!v)throw new AssertionError(why);}
 private static String hash(byte[] b)throws Exception{StringBuilder s=new StringBuilder();for(byte v:MessageDigest.getInstance("SHA-256").digest(b))s.append(String.format(Locale.ROOT,"%02x",v&255));return s.toString();}
 private static String copy(InputStream in,File out,String sha,BooleanSupplier cancel)throws Exception{try{return (String)copier.invoke(null,in,new File(out.getPath()+".new"),out,sha,cancel);}catch(InvocationTargetException e){Throwable t=e.getCause();if(t instanceof Exception)throw (Exception)t;throw (Error)t;}}
 private static void absent(File out,String why){check(!out.exists()&&!new File(out.getPath()+".new").exists(),why);}
 private static final class Tracked extends ByteArrayInputStream{boolean closed;Tracked(byte[] b){super(b);}public void close()throws IOException{closed=true;super.close();}}
 public static void main(String[] args)throws Exception{
  try{copier=OneImageHandoff.class.getDeclaredMethod("copyEncoded",InputStream.class,File.class,File.class,String.class,BooleanSupplier.class);copier.setAccessible(true);}catch(NoSuchMethodException e){throw new AssertionError("exact encoded snapshot copy API is missing");}
  mime=OneImageHandoff.class.getDeclaredMethod("detectMime",byte[].class,int.class,String.class);mime.setAccessible(true);extension=OneImageHandoff.class.getDeclaredMethod("extension",String.class);extension.setAccessible(true);
  Path base=args.length>0?Path.of(args[0]):Path.of("build","tmp","one-handoff-tests");Files.createDirectories(base);Path dir=Files.createTempDirectory(base,"owned-");
  try{
   byte[] source={(byte)137,80,78,71,13,10,26,10,1,2,3,4,5,6,7,8};File first=dir.resolve("first.png").toFile();Tracked read=new Tracked(source);
   check(hash(source).equals(copy(read,first,hash(source),()->false)),"reported SHA is original encoded source SHA");check(Arrays.equals(source,Files.readAllBytes(first.toPath())),"original encoded bytes preserved without rendering overlays");check(read.closed,"successful selected stream closed");check(!new File(first.getPath()+".new").exists(),"successful atomic commit leaves no pending file");
   byte[] next={9,8,7};File second=dir.resolve("second.jpg").toFile();copy(new Tracked(next),second,hash(next),()->false);check(Arrays.equals(source,Files.readAllBytes(first.toPath()))&&Arrays.equals(next,Files.readAllBytes(second.toPath())),"unique snapshots cannot mutate earlier playlist source");
   File changed=dir.resolve("changed.jpg").toFile();try{copy(new Tracked(next),changed,hash(source),()->false);throw new AssertionError("changed encoded input accepted");}catch(IOException expected){}absent(changed,"SHA mismatch removes owned pending source");
   File huge=dir.resolve("huge.jpg").toFile();InputStream generated=new InputStream(){long left=32L*1024*1024+1;public int read(){return left-->0?1:-1;}public int read(byte[] b,int o,int n){if(left<=0)return -1;n=(int)Math.min(n,left);Arrays.fill(b,o,o+n,(byte)1);left-=n;return n;}};try{copy(generated,huge,null,()->false);throw new AssertionError("oversize accepted");}catch(IOException expected){}absent(huge,"oversize failure removes owned pending source");
   File boundary=dir.resolve("exact-boundary.jpg").toFile();InputStream exact=new InputStream(){long left=32L*1024*1024;public int read(){return left-->0?1:-1;}public int read(byte[] b,int o,int n){if(left<=0)return -1;n=(int)Math.min(n,left);Arrays.fill(b,o,o+n,(byte)1);left-=n;return n;}};check(copy(exact,boundary,null,()->false).matches("[a-f0-9]{64}")&&boundary.length()==32L*1024*1024,"exact32MiB is accepted and hashed");check(!new File(boundary.getPath()+".new").exists(),"exact-boundary commit has no staging remainder");
   File canceled=dir.resolve("canceled.jpg").toFile();AtomicInteger polls=new AtomicInteger();Tracked stopped=new Tracked(source);try{copy(stopped,canceled,null,()->polls.incrementAndGet()>2);throw new AssertionError("canceled copy committed");}catch(InterruptedIOException expected){}absent(canceled,"canceled copy removes owned files");check(stopped.closed,"canceled stream closed");
   File broken=dir.resolve("broken.jpg").toFile();AtomicBoolean closed=new AtomicBoolean();InputStream failure=new InputStream(){public int read()throws IOException{throw new IOException("injected read failure");}public void close(){closed.set(true);}};try{copy(failure,broken,null,()->false);throw new AssertionError("read failure committed");}catch(IOException expected){}absent(broken,"read failure removes owned files");check(closed.get(),"failing source closed");
   File empty=dir.resolve("empty.jpg").toFile();try{copy(new Tracked(new byte[0]),empty,null,()->false);throw new AssertionError("empty image committed");}catch(IOException expected){}absent(empty,"empty source rejected and cleaned");
   try{copy(new Tracked(next),first,null,()->false);throw new AssertionError("existing snapshot overwritten");}catch(IOException expected){}check(Arrays.equals(source,Files.readAllBytes(first.toPath())),"existing snapshots never overwritten or deleted");
   File closeFail=dir.resolve("close-failure.jpg").toFile();InputStream badClose=new ByteArrayInputStream(source){public void close()throws IOException{throw new IOException("injected close failure");}};try{copy(badClose,closeFail,null,()->false);throw new AssertionError("source close failure committed");}catch(IOException expected){}absent(closeFail,"close failure cannot commit an unowned stream result");
   check("image/png".equals(mime.invoke(null,source,source.length,"image/jpeg")),"encoded PNG signature wins over wrong MIME metadata");check("png".equals(extension.invoke(null,"image/png")),"PNG snapshot has PNG extension");check("image/jpeg".equals(mime.invoke(null,new byte[]{(byte)255,(byte)216,(byte)255},3,null)),"JPEG identified without provider MIME");
   boolean rejected=false;try{mime.invoke(null,new byte[]{1,2,3},3,"application/octet-stream");}catch(InvocationTargetException expected){rejected=expected.getCause() instanceof IOException;}check(rejected,"unknown source type is rejected rather than relabeled JPEG");
   System.out.println("One encoded handoff PASS "+checks+" checks");
  }finally{try(var files=Files.list(dir)){for(Path f:(Iterable<Path>)files::iterator){if(!f.toAbsolutePath().getParent().equals(dir.toAbsolutePath()))throw new IOException("test cleanup boundary");Files.deleteIfExists(f);}}Files.deleteIfExists(dir);}
 }
}
